from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """

    def find_matching_close_brace(s: str, start: int = 0) -> int:
        """ Returns the index of the matching close brace that matches the open brace at `start` in string `s`."""
        stack = []
        for i, c in enumerate(enumerate(s[start:], start=start):
            if c == '(':
                stack.append(i)
            elif c == ')':
                return stack.pop()
        raise ValueError('No matching close brace found')

    def separate_groups(s: str) -> List[str]:
        """ Returns a list of strings, where each string is a group of parentheses."""
        groups = []
        start = 0
        for i, c in enumerate(s):
            if c == '(':
                try:
                    close = find_matching_close_brace(s, i)
                except ValueError:
                    continue
                groups.append(s[i + 1:close])
                i = close
            elif c == ')':
                break
        return groups

    return separate_groups(paren_string)
```

